// ═══════════════════════════════════════════════════════════════
// WORKFLOW UNIFICADO v3.2 - Estados Unificados (StatusGator)
// ═══════════════════════════════════════════════════════════════
// Estados unificados (basados en StatusGator webhook):
//   up          → Operational
//   warn        → Minor / Partial / Degraded
//   down        → Major / Critical / Outage
//   maintenance → Maintenance
// ═══════════════════════════════════════════════════════════════

const webhookData = $('Webhook').first().json.body;

// ─────────────────────────────────────────────────────────────────
// CONFIGURACIÓN DE ESTADOS UNIFICADOS (StatusGator style)
// ─────────────────────────────────────────────────────────────────
const UNIFIED_STATES = {
  up: { label: 'Operacional', emoji: '🟢' },
  warn: { label: 'Degradado', emoji: '🟡' },
  down: { label: 'Caído', emoji: '🔴' },
  maintenance: { label: 'Mantenimiento', emoji: '🔵' }
};

// ─────────────────────────────────────────────────────────────────
// 1. DETECTAR ORIGEN Y NORMALIZAR
// ─────────────────────────────────────────────────────────────────
let normalized = {};

// StatusGator envía: { service: {...}, status: 'up'|'warn'|'down'|'maintenance', ... }
// Monitor propio envía: { service, site, error_code, timestamp }
const isStatusGator = webhookData.service && typeof webhookData.service === 'object';

if (isStatusGator) {
  // ═══ STATUSGATOR ═══
  const svc = webhookData.service || {};
  const monitor = webhookData.monitor || {};
  const board = webhookData.board || {};

  // StatusGator usa: up, warn, down, maintenance
  const gatorStatus = (webhookData.status || 'up').toLowerCase();
  const prevStatus = (webhookData.previous_status || '').toLowerCase();
  const state = UNIFIED_STATES[gatorStatus] || UNIFIED_STATES['up'];

  normalized = {
    source: 'statusgator',
    service_name: `[SG] ${svc.name || monitor.display_name || 'Servicio Desconocido'}`,
    service_name_raw: svc.name || monitor.display_name || 'Servicio Desconocido',
    status: gatorStatus,
    status_label: state.label,
    status_emoji: state.emoji,
    previous_status: prevStatus,
    url: svc.status_page_url || svc.home_page_url || '',
    timestamp: webhookData.recorded_at || new Date().toISOString(),
    message: webhookData.message || null,
    details: webhookData.details || null,
    event_type: webhookData.type || null,
    raw_code: gatorStatus
  };
} else {
  // ═══ MONITOR PROPIO ═══
  const serviceName = webhookData.service || webhookData.site || 'Servicio Desconocido';
  const errorCode = String(webhookData.error_code || '000').trim();

  // Mapear códigos HTTP a estados unificados StatusGator
  let unifiedStatus = 'down';

  if (errorCode === '200' || errorCode === '302' || errorCode === '301' || errorCode === '204' || errorCode === '304') {
    unifiedStatus = 'up';
  } else if (errorCode === '000') {
    unifiedStatus = 'down'; // Sin conexión
  } else if (errorCode.startsWith('5')) {
    unifiedStatus = 'down'; // Errores de servidor
  } else if (errorCode.startsWith('4')) {
    unifiedStatus = 'warn'; // Errores de cliente (degradado)
  }

  const state = UNIFIED_STATES[unifiedStatus];

  normalized = {
    source: 'internal',
    service_name: serviceName,
    service_name_raw: serviceName,
    status: unifiedStatus,
    status_label: state.label,
    status_emoji: state.emoji,
    previous_status: null,
    url: webhookData.site || '',
    timestamp: webhookData.timestamp || new Date().toISOString(),
    message: null,
    details: null,
    event_type: null,
    raw_code: errorCode
  };
}

// ─────────────────────────────────────────────────────────────────
// 2. LEER ESTADOS ANTERIORES
// ─────────────────────────────────────────────────────────────────
let allStates = {};
let oldStatus = 'first_check';

const binaryData = $input.first().binary;
if (binaryData && binaryData.data) {
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
    const jsonContent = buffer.toString('utf8').trim();
    if (jsonContent && jsonContent !== '{}') {
      allStates = JSON.parse(jsonContent);
    }
    if (allStates[normalized.service_name]) {
      oldStatus = allStates[normalized.service_name].current || 'first_check';
    }
  } catch (error) {
    console.log('Error leyendo JSON:', error);
  }
}

// Para StatusGator, usar previous_status del webhook si está disponible
if (isStatusGator && normalized.previous_status) {
  oldStatus = normalized.previous_status;
}

// ─────────────────────────────────────────────────────────────────
// 3. DETECTAR CAMBIO
// ─────────────────────────────────────────────────────────────────
const hasChanged = (normalized.status !== oldStatus);
const isRecovery = hasChanged && normalized.status === 'up' && oldStatus !== 'up';
const isDown = hasChanged && normalized.status === 'down';
const isDegraded = hasChanged && normalized.status === 'warn';
const isMaintenance = hasChanged && normalized.status === 'maintenance';

// StatusGator ya filtra - solo envía webhooks cuando hay cambios
const shouldAlert = isStatusGator ? true : hasChanged;

// ─────────────────────────────────────────────────────────────────
// 4. ACTUALIZAR ESTADOS
// ─────────────────────────────────────────────────────────────────
if (!allStates[normalized.service_name]) {
  allStates[normalized.service_name] = {
    source: normalized.source,
    current: normalized.status,
    previous: null,
    last_change: normalized.timestamp,
    history: []
  };
} else {
  if (hasChanged) {
    allStates[normalized.service_name].history.push({
      from: oldStatus,
      to: normalized.status,
      timestamp: normalized.timestamp
    });
    if (allStates[normalized.service_name].history.length > 50) {
      allStates[normalized.service_name].history.shift();
    }
    allStates[normalized.service_name].last_change = normalized.timestamp;
  }
  allStates[normalized.service_name].previous = oldStatus;
  allStates[normalized.service_name].current = normalized.status;
  allStates[normalized.service_name].source = normalized.source;
}

// ─────────────────────────────────────────────────────────────────
// 5. RETORNAR DATOS NORMALIZADOS
// ─────────────────────────────────────────────────────────────────
return {
  json: {
    // Control de flujo
    alert: shouldAlert,

    // Datos normalizados
    source: normalized.source,
    service: normalized.service_name,
    service_raw: normalized.service_name_raw,
    url: normalized.url,

    // Estados unificados (up, warn, down, maintenance)
    status: normalized.status,
    status_label: normalized.status_label,
    status_emoji: normalized.status_emoji,
    raw_code: normalized.raw_code,

    old_status: oldStatus,
    old_status_label: UNIFIED_STATES[oldStatus]?.label || 'Primer Chequeo',

    // Clasificación
    is_recovery: isRecovery,
    is_down: isDown,
    is_degraded: isDegraded,
    is_maintenance: isMaintenance,

    // Detalles (StatusGator)
    message: normalized.message,
    details: normalized.details,
    event_type: normalized.event_type,

    // Metadata
    timestamp: normalized.timestamp,
    all_states: allStates,
    json_to_save: JSON.stringify(allStates, null, 2)
  }
};

